{
  "name": "shake",
  "version": "0.3.1",
  "description": "Shrink a long session by replacing old tool results with saved-file placeholders during compaction",
  "author": {
    "name": "Taras Serhiichuk"
  },
  "userConfig": {
    "thresholdTokens": {
      "type": "number",
      "title": "Shake threshold (tokens)",
      "description": "Used context, in tokens, at which a shake starts after an answer.",
      "default": 150000
    },
    "floorShare": {
      "type": "number",
      "title": "Floor share",
      "description": "Least share of the used context that a threshold shake must free. A shake rewrites the prompt cache of what stays, so a small shake costs more than it saves.",
      "default": 0.33
    },
    "idleShake": {
      "type": "boolean",
      "title": "Idle shake",
      "description": "Shake with no floor when the prompt cache expires, also at once on a resume after a longer pause. The next request writes the whole cache in any case, so this shake costs nothing extra.",
      "default": true
    },
    "cacheTtlMinutes": {
      "type": "number",
      "title": "Prompt cache lifetime (minutes)",
      "description": "0 reads it from the session's newest cache write (60 or 5). Set a number only to override.",
      "default": 0
    }
  }
}
